a/logo-nutre.png","alt":"Logo Nutre - DF"}},{"name":"Instituto Equilibraí","role":"Dinâmica educativa · fauna e flora do Cerrado, com Fernanda Garcia"}]},"info":{"eyebrow":"Antes de ir","title":"Informações importantes","items":[{"id":"chegada","title":"Horário e chegada","body":"A chegada e a recepção começam às 17h15, no Cápsula Bar, às margens do Lago Paranoá. A tolerância de chegada vai até as 17h30, horário de início da remada. A programação termina às 20h30."},{"id":"o-que-levar","title":"O que levar","body":"Roupas confortáveis que possam molhar, muda de roupa, toalha, tapete próprio para a Superioga, garrafa de água, repelente e um agasalho leve para a noite."},{"id":"criancas","title":"Participação de crianças","body":"Crianças são bem-vindas e participam somente acompanhadas por um responsável. A dinâmica educativa é opcional e os menores continuam sob supervisão adequada de seus responsáveis.\n\nCada criança paga o mesmo ingresso (R$ 160) e conta na capacidade total de 24 participantes. Durante a remada, o uso de colete salva-vidas adequado é obrigatório.","email":true},{"id":"seguranca","title":"Segurança na remada","body":"A remada é realizada em canoas havaianas, com acompanhamento da equipe Alma Azul Academy e uso obrigatório de colete salva-vidas para todos os participantes, inclusive crianças, com colete adequado.\n\nA realização da atividade na água depende de condições seguras de navegação."},{"id":"alimentacao","title":"Lanche saudável","body":"O ingresso inclui o lanche saudável da Nutre - DF, servido às 19h30, sem cobrança adicional."},{"id":"clima","title":"Condições climáticas","body":"Se as condições climáticas impedirem a realização segura das atividades, o evento inteiro será reagendado — remada, Superioga, lanche saudável, massagem e reflexologia e Educação Ambiental — e a nova data será comunicada aos participantes.\n\nO evento não é realizado em versão parcial nessas condições."},{"id":"cancelamento","title":"Política de cancelamento","body":"Você pode solicitar o cancelamento até 21 de novembro de 2026, às 12h00 (horário de Brasília), escolhendo entre crédito para outra experiência da Alma Azul Academy ou reembolso, conforme a política aplicável e os direitos do consumidor.\n\nAs solicitações são atendidas pela nossa equipe, pelos canais oficiais de atendimento."}]},"arrival":{"startTime":"17:15","toleranceUntil":"17:30"},"cancellation":{"deadline":"2026-11-21T12:00:00-03:00","timeZone":"America/Sao_Paulo","summary":"crédito para outra experiência da Alma Azul Academy ou reembolso, pelo atendimento da nossa equipe"},"reservation":{"eyebrow":"Celebre os novos ciclos com a gente","title":"Garanta a sua vaga","ctaLabel":"Garantir minha vaga","maxPerOrder":6,"notice":"Traga seu próprio tapete para a Superioga. Crianças participam somente acompanhadas por um responsável.","comingSoon":false,"image":{"src":"/images/eventos/essencia-lua-cheia/reserva-capsula-noite.webp","alt":"Cápsula Bar iluminado à noite, visto do Lago Paranoá, com as luzes refletidas na água e canoas no píer"}}}}$json$::jsonb then
    raise exception 'EVENTO_CONTEUDO_ABERTO: o conteúdo não ficou igual ao aprovado sem "em breve"';
  end if;
  if (select status from public.sessions where id = target_session.id) <> 'OPEN' then
    raise exception 'EVENTO_SESSAO_NAO_ABRIU';
  end if;
  if public.available_spots(target_session.id) <> 24 then
    raise exception 'EVENTO_VAGAS: esperadas 24 vagas livres depois da abertura';
  end if;
  if (select count(*) from public.list_public_event_sessions('essencia-lua-cheia') x where x.id = target_session.id and x.availability = 'AVAILABLE') <> 1
     or not exists (select 1 from public.get_booking_session(target_session.id)) then
    raise exception 'EVENTO_SEM_VENDA: a sessão não ficou reservável';
  end if;
  select md5(coalesce(string_agg(x::text, '|' order by x::text), '')) into regulars_after from public.list_public_regular_catalog() x;
  select (select coalesce(count(*)::text || ' evento(s) [' || string_agg(e.slug || '=' || e.status, ', ' order by e.slug) || '] ' || md5(string_agg(e.id::text || e.status || e.editorial_content::text || coalesce((
            select string_agg(s.id::text || s.status::text || s.starts_at::text || s.capacity || s.price_cents || s.duration_minutes, ',' order by s.id)
            from public.sessions s where s.experience_id = e.id), ''), '|' order by e.id)), 'nenhum outro evento')
          from public.experiences e where e.kind = 'EVENT' and e.slug <> 'essencia-lua-cheia') into others_after;
  if regulars_before <> regulars_after or others_before <> others_after then
    raise exception 'EVENTO_ISOLAMENTO: o catálogo regular ou outra edição mudou';
  end if;
  raise notice 'EVENTO_VENDAS_ABERTAS sessionId=%', target_session.id;
end;
$abertura$;

commit;
